    status.value=body.readonly||(body.approving?'Review: approve, correct, or request changes':body.label?`Label: ${body.label.state}`:'Not labelled yet');
    comments.value=(await liveApi.comments(props.state.ref,it.id)).comments;if(body.detect?.auto&&item.value===it)runDetect(body.detect.auto,true);}catch(e){status.value=e.message;}}
