  if(!accepted){reason.value='';reasonOpen.value=true;return;}const W=meta.value.photo.width,H=meta.value.photo.height;busy.value=true;
  try{const body=await liveApi.saveLabel(props.state.ref,item.value.id,{action:'approve',review:meta.value.review,shapes:toBackend(shapes.value,W,H),nothing_to_mark:empty.value&&!shapes.value.length});
