// The class of a shape, asked as soon as it is drawn, and when a shape is clicked with Select: a small panel beside it
// with the project's classes (type to filter, ↑/↓ to choose), Delete, and Save (Enter). The next shape is drawn in the
// class chosen last.
const classPop=ref(null);const popInput=ref(null);
const popShape=computed(()=>classPop.value?shapes.value.find(sh=>sh.id===classPop.value.id):null);
const popMatches=computed(()=>{if(!classPop.value)return [];const t=classPop.value.text.trim().toLowerCase();const all=props.state.classes;
  if(!t||all.some(c=>c.name.toLowerCase()===t))return all;return all.filter(c=>c.name.toLowerCase().includes(t));});
// The panel sits at the top-left corner of the photo (asked for by the user on 2026-10-16): always in view, never cut off.
const popStyle={left:'12px',top:'12px'};
function openPop(shape,isNew){const at=Math.max(0,props.state.classes.findIndex(c=>c.name===shape.kind));classPop.value={id:shape.id,text:shape.kind,at,isNew,error:''};
  nextTick(()=>{popInput.value?.focus();popInput.value?.select();});}
function closePop(){classPop.value=null;}
function popStep(step){const pop=classPop.value,list=popMatches.value;if(!pop||!list.length)return;const at=list.findIndex(c=>c.name===pop.text);const next=list[((at<0?pop.at:at)+step+list.length)%list.length];
  pop.text=next.name;pop.at=props.state.classes.findIndex(c=>c.name===next.name);pop.error='';}
function savePop(name){const pop=classPop.value,sh=popShape.value;if(!pop||!sh){closePop();return;}const t=String(name||pop.text).trim().toLowerCase();
  const found=props.state.classes.find(c=>c.name.toLowerCase()===t)||(popMatches.value.length===1?popMatches.value[0]:null);
  if(!found){pop.error=`Choose one of the classes: ${props.state.classes.map(c=>c.name).join(', ')}.`;nextTick(()=>popInput.value?.focus());return;}
  if(found.name!==sh.kind){if(!pop.isNew)remember();sh.kind=found.name;dirty.value=true;}kind.value=found.name;closePop();}
function deletePop(){const pop=classPop.value;if(!pop)return;if(pop.isNew&&history.value.length)shapes.value=history.value.pop();else{remember();shapes.value=shapes.value.filter(sh=>sh.id!==pop.id);}
  selected.value=null;closePop();}
function pickShape(shape){selected.value=shape.id;kind.value=shape.kind;pickedPoint.value=null;if(tool.value==='select'&&!locked.value)openPop(shape,false);}
// "Start from walls that are already there" (the old editor's Detect, views._detect): the walls the app sent, what a
// model finds, or the empty photo. A model is started when it is not running; the editor asks again every 4 seconds
// until it answers. A "Basic Detector" answer is tidied here by the old editor's rules (geometry.js tidyUp), and
// Ctrl+Z shows what the model drew. Whatever comes is a head start: it replaces what is drawn, and is saved only with
// the person's own save.
const detectOpen=ref(false);const detecting=ref(null);const detectError=ref('');const detectChoice=ref('');let pollTimer=null;
function openDetect(){if(refuseLocked())return;if(!live.value){pendingTool('Find Objects with AI');return;}
  if(!meta.value?.detect){hint.value=meta.value?.readonly||(meta.value?.approving?'This label waits for approval: a model does not draw on it here.':'A model cannot mark the walls here.');return;}
  detectChoice.value=meta.value.detect.preference||'';detectError.value='';detectOpen.value=true;}
function stopDetect(){clearTimeout(pollTimer);pollTimer=null;detecting.value=null;}
async function runDetect(id,auto=false,refine=null){clearTimeout(pollTimer);const it=item.value;const source=meta.value?.detect?.sources.find(x=>x.id===id);if(!it||!source)return;detectError.value='';
  if(!detecting.value)detecting.value={id,name:source.name,title:`Asking ${source.name}`,now:'asking the model',steps:[],auto,refine};
  try{const body=await liveApi.detect(props.state.ref,it.id,id);if(item.value!==it||!detecting.value)return;
    if(body.state==='waiting'){detecting.value={...body,id,auto,refine};pollTimer=setTimeout(()=>runDetect(id,auto,refine),4000);return;}
    if(refine)applyRefine(body,refine);else applyDetected(body,auto);}
  catch(e){if(item.value!==it)return;detecting.value=null;detectError.value=e.message;if(!detectOpen.value)hint.value=`${source.name} did not mark the walls. ${e.message}`;}}
function wordsOf(report){const did=[];if(report.cut)did.push(`cut at ${report.cut} room corner${report.cut===1?'':'s'}`);
  if(report.straightened)did.push(`${report.straightened} wall${report.straightened===1?'':'s'} brought to ${report.straightened===1?'its':'their'} corners`);
  if(report.moved)did.push(`${report.moved} door or window${report.moved===1?'':'s'} brought inside ${report.moved===1?'its':'their'} wall`);return did.join(', ');}
function applyDetected(body,auto){const W=meta.value.photo.width,H=meta.value.photo.height;detecting.value=null;detectOpen.value=false;closePop();cancelDrawing();
  remember();shapes.value=fromBackend(body.shapes,W,H);let said=`${body.name} marked ${body.shapes.length} shape${body.shapes.length===1?'':'s'}.`;
  if(body.tidy&&body.shapes.length){const report=tidyUp(structuredCloneRaw(body.shapes));const words=wordsOf(report);if(words){remember();shapes.value=fromBackend(report.shapes,W,H);said=`${body.name}: tidied by itself, ${words}.`;}}
  meta.value.started_from=body.started_from;meta.value.started_model=body.started_model;empty.value=false;selected.value=null;dirty.value=true;
  hint.value=`${auto?'Your choice for a photo nobody has drawn on. ':''}${said} A head start, not a label: check every corner${body.tidy?'; Ctrl+Z shows what the model drew':''}.${body.research_only?' The model is for research or evaluation only, and the label says so.':''}`;}
// AI refine: the selected shape is replaced by the shape of its kind that a model finds in the same place (the model
// the person chose for new photos, else the first one offered), tidied by the same rules as Auto annotation. Only that
// shape changes, as one step of Undo; when the model finds nothing of its kind there, nothing changes.
function refineSelected(){if(refuseLocked())return;if(!live.value){pendingTool('AI refine');return;}
  const target=shapes.value.find(x=>x.id===selected.value);if(!target){hint.value='Select a shape first: AI refine replaces it with the shape a model finds in the same place.';return;}
  const detect=meta.value?.detect;if(!detect?.sources?.length){hint.value=meta.value?.readonly||'A model cannot mark the walls here.';return;}
  const source=detect.sources.find(x=>x.id===detect.preference)||detect.sources[0];closePop();runDetect(source.id,false,target.id);}
function applyRefine(body,targetId){const W=meta.value.photo.width,H=meta.value.photo.height;detecting.value=null;
  const target=shapes.value.find(x=>x.id===targetId);if(!target){hint.value='The shape was removed while the model looked at the photo. Nothing was changed.';return;}
  const tidied=body.tidy&&body.shapes.length?tidyUp(structuredCloneRaw(body.shapes)).shapes:body.shapes;
  const match=bestMatch(target,fromBackend(tidied,W,H));
  if(!match){hint.value=`${body.name} found no ${target.kind} in the same place as this one. Nothing was changed.`;return;}
  remember();target.points=structuredCloneRaw(match.shape.points);target.corner=match.shape.corner;target.cornerTypes=match.shape.cornerTypes;target.cornerCount=match.shape.cornerCount;
  dirty.value=true;pickedPoint.value=null;selected.value=target.id;
  hint.value=`${body.name} refined this ${target.kind}: its corners now follow what the model sees (${Math.round(match.share*100)}% the same place as yours). Check every corner; Ctrl+Z brings yours back.${body.research_only?' The model is for research or evaluation only.':''}`;}
async function startFrom(start){const it=item.value;detectError.value='';stopDetect();
  try{const body=await liveApi.editor(props.state.ref,it.id,null,start);if(item.value!==it)return;const W=body.photo.width,H=body.photo.height;closePop();cancelDrawing();
    remember();shapes.value=fromBackend(body.shapes,W,H);meta.value.started_from=body.started_from;meta.value.started_model=body.started_model||'';empty.value=false;selected.value=null;dirty.value=true;detectOpen.value=false;
    hint.value=start==='blank'?'Everything was removed. Draw the walls by hand.':`Started from ${start==='correction'?"the walls the app's user confirmed":"the walls the app's own AI marked"}. Check every corner.`;}
  catch(e){detectError.value=e.message;}}
async function saveDetectChoice(){try{const body=await liveApi.detectPreference(props.state.ref,detectChoice.value);meta.value.detect.preference=body.preference;detectError.value='';detectOpen.value=false;
  hint.value=body.preference?'Saved: from now on that model marks the walls first on a photo nobody has drawn on.':'Saved: no model marks the walls by itself.';}catch(e){detectError.value=e.message;}}
function undo(){if(!history.value.length)return;pickedPoint.value=null;future.value.push(structuredCloneRaw(shapes.value));shapes.value=history.value.pop();dirty.value=true;}
function redo(){if(!future.value.length)return;pickedPoint.value=null;history.value.push(structuredCloneRaw(shapes.value));shapes.value=future.value.pop();dirty.value=true;}
function syncBatch(){if(live.value)return;const b=props.state.batches.find(b=>b.id===item.value.batchId);if(!b)return;const group=props.state.images.filter(i=>i.batchId===b.id);b.status=group.every(i=>i.state==='Accepted')?'Dataset':group.some(i=>i.state==='In review')?'In review':batchColumn({...b,status:'Annotating'});}
function save(review=false){if(draft.value.length){status.value='Finish or cancel the polygon before saving.';return;}if(live.value)return saveLive(review);if(review&&!shapes.value.length&&!empty.value){status.value='Draw an annotation or mark this image as having no objects.';return;}item.value.shapes=structuredCloneRaw(shapes.value);item.value.state=review?'In review':(item.value.state==='Changes requested'?'Changes requested':'Unlabeled');item.value.noObjects=empty.value;syncBatch();dirty.value=false;status.value=review?'Sent to review locally':'Draft saved locally';}
function review(accepted){if(live.value)return reviewLive(accepted);if(dirty.value){status.value='Save your changes before reviewing.';return;}if(accepted&&!item.value.shapes.length&&!item.value.noObjects){status.value='Add an annotation or mark no objects before approving.';return;}item.value.state=accepted?'Accepted':'Changes requested';syncBatch();status.value=accepted?'Accepted in local dataset preview':'Changes requested locally';}
function selectImage(i){if(dirty.value||draft.value.length){pendingIndex.value=i;leaving.value=true;return;}load(i);}
function load(i){cancelDrawing();closePop();pickedPoint.value=null;stopDetect();detectOpen.value=false;hint.value='';index.value=i;pan.value={x:0,y:0};aspect.value=2;shapes.value=structuredCloneRaw(item.value.shapes);empty.value=!!item.value.noObjects;history.value=[];future.value=[];draft.value=[];dirty.value=false;selected.value=null;status.value='Local preview';if(live.value){meta.value=null;fetchEditor();}}
function close(){if(dirty.value||draft.value.length){pendingIndex.value=null;leaving.value=true;}else emit('close');}
function discard(){leaving.value=false;if(pendingIndex.value===null)emit('close');else load(pendingIndex.value);}
function addTag(){if(live.value){const v=tag.value.trim();tag.value='';if(!v)return;liveApi.tag(props.state.ref,item.value.id,{add:v}).then(b=>{item.value.tags=b.tags;}).catch(e=>{status.value=e.message;});return;}if(tag.value.trim()&&!item.value.tags.includes(tag.value.trim()))item.value.tags.push(tag.value.trim());tag.value='';}
</script>
<template>
<div class="annotation-editor">
  <header class="editor-header"><UiButton @click="close"><ArrowLeft :size="16"/> Back</UiButton><strong>{{ item?.name }}</strong><UiBadge v-if="!live" tone="purple">Coming soon</UiBadge><span role="status">{{ dirty ? 'Unsaved changes' : status }}</span><UiButton :disabled="busy||!!meta?.readonly||!!meta?.approving" @click="save()"><Save :size="15"/> Save draft</UiButton><UiButton variant="primary" :disabled="busy||!!meta?.readonly||!!meta?.approving" @click="save(true)"><Check :size="15"/> Send to review</UiButton></header>
  <div v-if="item" class="editor-layout"><aside class="editor-left"><div class="editor-panel-tabs"><button v-for="entry in panelItems" :key="entry.name" :class="{active:panel===entry.name}" @click="panel=entry.name"><span><component :is="entry.icon" :size="19"/></span>{{entry.name}}</button></div>
    <template v-if="panel==='Labels'"><h3>Annotations <UiBadge>{{ shapes.length }}</UiBadge></h3><p class="editor-group">Group: {{state.batches.find(b=>b.id===item.batchId)?.name||'Project images'}}</p><div class="editor-label-tabs"><button v-for="name in ['Classes','Layers']" :key="name" :aria-pressed="layerTab===name" @click="layerTab=name">{{name}}</button></div><p v-if="layerTab==='Layers'">{{shapes.length? 'Select an annotation layer below to edit its points.' : 'No annotation layers yet.'}}</p><div v-if="layerTab==='Classes'" class="unused-classes"><strong>Available classes</strong><span v-for="c in state.classes" :key="c.name"><i :style="{background:c.color}"/>{{c.name}}</span></div><UiButton class="find-ai" title="Start from walls a model finds (M)" @click="openDetect"><Sparkles :size="15"/>Find Objects with AI</UiButton><label class="field-label">Class<select v-model="kind" class="text-input"><option v-for="c in state.classes" :key="c.name">{{ c.name }}</option></select></label><label class="field-label">Corner type<select v-model="corner" class="text-input"><option value="room">Room corner</option><option value="image_edge">Image edge</option></select></label><div class="shape-list"><button v-for="(shape,i) in shapes" :key="shape.id" :class="{active:selected===shape.id}" @click="selected=shape.id;kind=shape.kind"><span :style="{background:state.classes.find(c=>c.name===shape.kind)?.color}"/>{{ shape.kind }} {{ i+1 }}<small>{{ shape.points.length }} points</small></button></div><UiButton :disabled="!selected" @click="removeSelected"><Trash2 :size="14"/> Remove selected</UiButton><label class="field-label">Tags</label><div class="component-row"><UiBadge v-for="t in item.tags" :key="t">{{ t }}</UiBadge></div><form @submit.prevent="addTag"><input v-model="tag" class="text-input" aria-label="Image tag" placeholder="Add a tag"><UiButton type="submit">Add tag</UiButton></form></template>
    <template v-else-if="panel==='Attributes'"><h3>Image attributes</h3><dl><dt>Source</dt><dd>{{ live?'Project photo':item.sample?'Synthetic room':'Local browser file' }}</dd><dt>Canvas coordinates</dt><dd>{{ live&&meta?`${meta.photo.width} × ${meta.photo.height} photo pixels (drawn in 600 × 300 units)`:'600 × 300 preview units' }}</dd><dt>Status</dt><dd>{{ item.state }}</dd></dl><label class="check-line"><input v-model="empty" type="checkbox" @change="dirty=true"> No objects to mark</label><p v-if="!live">Preview geometry only. Backend coordinate conversion is not connected.</p></template>
    <template v-else-if="panel==='Comments'"><h3>Comments</h3><p v-if="!comments.length">No comments yet.</p><p v-for="(c,i) in comments" :key="i" class="comment-preview">{{ typeof c==='string'?c:`${c.by}: ${c.text}` }}</p><form @submit.prevent="addComment"><textarea v-model="comment" class="text-input" aria-label="Comment" placeholder="Add a review note"/><UiButton type="submit">{{ live?'Add comment':'Add local comment' }}</UiButton></form></template>
    <template v-else-if="panel==='History'"><h3>Editing history</h3><p>{{ history.length }} changes available to undo.</p><p>{{ future.length }} changes available to redo.</p><p v-if="!live">History is kept for this editing session only.</p><template v-else><p v-if="!meta?.history?.length">No saves of this label yet.</p><p v-for="(h,i) in meta?.history||[]" :key="i">{{ h.state }} · {{ h.walls }} walls, {{ h.openings }} openings{{ h.faults?` · ${h.faults} to fix`:'' }} · {{ h.by }} · {{ new Date(h.at).toLocaleString() }}</p></template></template>
    <template v-else-if="panel==='Job details'"><h3>Job details</h3><dl><dt>Batch</dt><dd>{{state.batches.find(b=>b.id===item.batchId)?.name||'Project images'}}</dd><dt>Assignment</dt><dd>{{state.batches.find(b=>b.id===item.batchId)?.assignee||'Unassigned'}}</dd><dt>Instructions</dt><dd>{{state.batches.find(b=>b.id===item.batchId)?.instructions||'No instructions added.'}}</dd></dl></template><template v-else><h3>Raw annotation preview</h3><pre>{{ JSON.stringify(shapes,null,2) }}</pre></template>
  </aside><section class="editor-canvas-area"><div class="editor-toolbar"><button v-for="t in [{id:'pan',label:'Pan image (H)',icon:Hand},{id:'select',label:'Select / move points (V)',icon:MousePointer2},{id:'polygon',label:'Draw polygon (P)',icon:Pentagon},{id:'box',label:'Draw box (B)',icon:Square},{id:'split',label:'Split a shape in two (S)',icon:Scissors}]" :key="t.id" class="icon-button" :aria-label="t.label" :title="t.label" :aria-pressed="tool===t.id" @click="setTool(t.id)"><component :is="t.icon" :size="20"/></button><button v-for="entry in [{name:'Brush / mask painting',icon:Brush},{name:'Rotate image',icon:RefreshCw},{name:'Smart selection',icon:MousePointer2},{name:'Auto annotation',icon:WandSparkles,label:'Auto annotation: start from walls a model finds (M)',run:openDetect},{name:'AI refine',icon:Sparkles,label:'AI refine: replace the selected shape with the one a model finds in the same place',run:refineSelected}]" :key="entry.name" class="icon-button" :aria-label="entry.label||entry.name+' - coming soon'" :title="entry.label||entry.name+' - coming soon'" @click="entry.run?entry.run():pendingTool(entry.name)"><component :is="entry.icon" :size="20"/></button><button class="icon-button" aria-label="Comments" @click="panel='Comments'"><MessageSquare :size="20"/></button><button class="icon-button" aria-label="Undo" :disabled="!history.length" @click="undo"><Undo2 :size="20"/></button><button class="icon-button" aria-label="Redo" :disabled="!future.length" @click="redo"><Redo2 :size="20"/></button><button class="icon-button" aria-label="Toggle annotations" :aria-pressed="overlays" @click="overlays=!overlays"><Eye :size="20"/></button><button class="icon-button" aria-label="Mark image as no objects" :aria-pressed="empty" @click="empty=!empty;dirty=true"><CircleOff :size="20"/></button></div>
    <div ref="scrollBox" class="canvas-scroll" :style="room.h?{maxHeight:room.h+'px'}:{}"><div class="canvas-stage" :style="{width:stageWidth,minWidth:0,filter:`brightness(${brightness}%)`,aspectRatio:aspect,transform:`translate(${pan.x}px,${pan.y}px)`}"><RoomArt plain v-if="item.sample" :variant="item.variant||0"/><img v-else :src="item.url" :alt="item.name" @load="imageLoaded"><svg ref="canvas" :class="['annotation-overlay',`tool-${tool}`]" viewBox="0 0 600 300" preserveAspectRatio="none" @pointerdown="down" @pointermove="move" @pointerup="finish" @pointerleave="leave" @dblclick="dbl">
      <g v-if="overlays"><g v-for="shape in shapes" :key="shape.id" :style="{pointerEvents:tool==='select'?'auto':'none'}"><polygon class="shape" :data-id="shape.id" :points="pts(shape.points)" :fill="colorOf(shape)" :fill-opacity="selected===shape.id?.32:.18" :stroke="colorOf(shape)" :stroke-width="selected===shape.id?3:2" stroke-linejoin="round" vector-effect="non-scaling-stroke" @pointerdown.stop="pickShape(shape)"/><template v-if="tool==='select'||selected===shape.id"><ellipse v-for="(p,i) in shape.points" :key="i" :class="['vertex',{picked:pickedPoint?.id===shape.id&&pickedPoint.i===i}]" :cx="p[0]" :cy="p[1]" v-bind="handle(pickedPoint?.id===shape.id&&pickedPoint.i===i?7:selected===shape.id?5:4)" :fill="pickedPoint?.id===shape.id&&pickedPoint.i===i?'#dc2626':'#fff'" :stroke="pickedPoint?.id===shape.id&&pickedPoint.i===i?'#fff':selected===shape.id?'#0f172a':colorOf(shape)" :stroke-width="pickedPoint?.id===shape.id&&pickedPoint.i===i?2:1.5" vector-effect="non-scaling-stroke" @pointerdown="beginMove($event,shape,i)"/></template></g></g>
      <g class="drawing-layer" pointer-events="none">
        <g v-if="cursor&&!drawing&&(tool==='box'||tool==='polygon')" class="guides"><line x1="0" x2="600" :y1="cursor[1]" :y2="cursor[1]" vector-effect="non-scaling-stroke"/><line y1="0" y2="300" :x1="cursor[0]" :x2="cursor[0]" vector-effect="non-scaling-stroke"/></g>
        <template v-if="draft.length"><polygon v-if="draft.length>=2&&cursor" :points="pts([...draft,closing?draft[0]:cursor])" :fill="draftColor()" fill-opacity=".1" stroke="none"/><polyline :points="pts([...draft,...(cursor?[closing?draft[0]:cursor]:[])])" fill="none" :stroke="draftColor()" stroke-width="2" stroke-dasharray="7 5" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"/><ellipse v-for="(p,i) in draft" :key="'d'+i" :cx="p[0]" :cy="p[1]" v-bind="handle(i===0?(closing?9:7):4)" :fill="i===0?'#dc2626':'#fff'" :stroke="i===0?'#fff':'#0f172a'" stroke-width="1.5" vector-effect="non-scaling-stroke"/></template>
        <template v-if="boxStart"><polygon :points="pts(boxCorners(boxStart,cursor||boxStart))" :fill="draftColor()" fill-opacity=".1" :stroke="draftColor()" stroke-width="2" stroke-dasharray="7 5" vector-effect="non-scaling-stroke"/><ellipse :cx="boxStart[0]" :cy="boxStart[1]" v-bind="handle(6)" fill="#dc2626" stroke="#fff" stroke-width="1.5" vector-effect="non-scaling-stroke"/><ellipse v-if="cursor" :cx="cursor[0]" :cy="cursor[1]" v-bind="handle(4)" fill="#fff" stroke="#0f172a" stroke-width="1.5" vector-effect="non-scaling-stroke"/></template>
        <template v-if="cutFrom"><line :x1="cutFrom[0]" :y1="cutFrom[1]" :x2="(cursor||cutFrom)[0]" :y2="(cursor||cutFrom)[1]" stroke="#dc2626" stroke-width="2.5" stroke-dasharray="8 5" stroke-linecap="round" vector-effect="non-scaling-stroke"/><ellipse :cx="cutFrom[0]" :cy="cutFrom[1]" v-bind="handle(6)" fill="#dc2626" stroke="#fff" stroke-width="1.5" vector-effect="non-scaling-stroke"/></template>
      </g></svg>
      <div v-if="classPop&&popShape" class="class-pop" :style="popStyle" role="dialog" aria-label="Annotation editor" @pointerdown.stop>
        <header><strong>Annotation editor</strong><button class="icon-button" aria-label="Close the annotation editor" @click="savePop()"><X :size="15"/></button></header>
        <input ref="popInput" v-model="classPop.text" class="text-input" aria-label="Class of this shape" autocomplete="off" @input="classPop.error=''" @keydown.enter.prevent="savePop()" @keydown.down.prevent="popStep(1)" @keydown.up.prevent="popStep(-1)" @keydown.esc.prevent.stop="savePop()">
        <ul role="listbox"><li v-for="c in popMatches" :key="c.name" role="option" :aria-selected="c.name===classPop.text" :class="{active:c.name===classPop.text}" @click="savePop(c.name)"><i :style="{background:c.color}"/>{{ c.name }}<small v-if="c.trained===false" class="label-only">label only</small></li></ul>
        <p v-if="classPop.error" class="field-error" role="alert">{{ classPop.error }}</p>
        <div class="class-pop-actions"><UiButton class="danger" @click="deletePop"><Trash2 :size="13"/> Delete</UiButton><UiButton variant="primary" @click="savePop()">Save (Enter)</UiButton></div>
      </div></div></div>
    <div class="editor-help" v-if="tool==='polygon'"><span>{{ draft.length?(closing?'Click the red point to close the polygon.':`${draft.length} point${draft.length===1?'':'s'}. Click the red first point, double-click or press Enter to finish; Backspace takes back the last point.`):'Click to place the first corner. Corners snap to other corners and to the photo edge.' }}</span><UiButton :disabled="draft.length<3" @click="finishPolygon">Finish polygon</UiButton><UiButton :disabled="!draft.length" @click="cancelDrawing">Cancel (Esc)</UiButton></div><div class="editor-help" v-else-if="tool==='box'"><span>{{ boxStart?'Click the opposite corner to finish the box. Esc cancels.':'Click one corner, then the opposite corner, or drag from corner to corner.' }}</span><UiButton v-if="boxStart" @click="cancelDrawing">Cancel (Esc)</UiButton></div><div class="editor-help" v-else-if="tool==='split'"><span>{{ cutFrom?'Click on the other side of the shape: the dashed line is the cut.':'Click on one side of a shape, then on the other: the line cuts it in two. A click inside the shape becomes the new corner.' }}</span><UiButton v-if="cutFrom" @click="cancelDrawing">Cancel (Esc)</UiButton></div><div class="editor-help" v-else-if="tool==='pan'">Drag the image to pan.</div><div class="editor-help" v-else><span>{{ pickedPoint?'Corner selected: drag it, or press Delete to remove it.':selected?'Click a corner to select it, double-click an edge to add one. Corners snap to other corners.':'Click a shape or one of its corners. Straighten keeps only the real corners.' }}</span><UiButton :disabled="!pickedPoint" @click="removePoint"><Trash2 :size="14"/> Delete point (Del)</UiButton><UiButton :disabled="!shapes.length" :title="selected?'Keep only the corners of the selected shape':'Keep only the corners of every shape'" @click="straighten">Straighten{{ selected?'':' all' }} (R)</UiButton></div><p v-if="detecting&&!detectOpen" class="editor-hint" role="status">{{ detecting.title }}: {{ detecting.now }}{{ detecting.seconds?` (${detecting.seconds} s)`:"" }}… <button class="link-button" @click="stopDetect">Stop</button></p><p v-if="hint" class="editor-hint" role="status">{{ hint }}</p>
    <footer class="editor-controls"><button class="icon-button" aria-label="Zoom out" @click="zoom=Math.max(50,zoom-25)"><Minus :size="16"/></button><span>{{ zoom }}%</span><button class="icon-button" aria-label="Zoom in" @click="zoom=Math.min(250,zoom+25)"><Plus :size="16"/></button><UiButton @click="zoom=100;brightness=100;pan={x:0,y:0}">Reset view</UiButton><label>Brightness <input v-model="brightness" type="range" min="50" max="150"></label><button class="icon-button" aria-label="Editor help" @click="pendingTool('Editor help')"><Keyboard :size="18"/></button></footer></section>
    <aside class="editor-right"><p class="editor-batch-title">{{state.batches.find(b=>b.id===item.batchId)?.name||'Project images'}}</p><div class="editor-pagination"><UiButton :disabled="index===0" @click="selectImage(index-1)">←</UiButton><span>{{ index+1 }} / {{ scopedImages.length }}</span><UiButton :disabled="index===scopedImages.length-1" @click="selectImage(index+1)">→</UiButton></div><UiButton :disabled="busy||(live&&!meta?.approving)" @click="review(true)"><Check :size="16"/> {{ live?'Approve':'Approve locally' }}</UiButton><UiButton :disabled="busy||(live&&!meta?.approving)" @click="review(false)"><X :size="16"/> Request changes</UiButton><UiBadge>{{ item.state }}</UiBadge><button v-for="(image,i) in scopedImages" :key="image.id" :class="['editor-thumb',{active:index===i}]" @click="selectImage(i)"><RoomArt v-if="image.sample" :variant="image.variant||0"/><img v-else :src="image.thumb||image.url" :alt="image.name" @error="image.thumb=''"><span>{{ image.name }}</span></button></aside>
  </div><UiDialog class="detect-dialog" :open="detectOpen" title="Start from walls that are already there" @close="detectOpen=false">
    <p class="dialog-description">Whatever you choose is a head start, not a label: you check every corner and send it to review. <strong>What is drawn now is thrown away and replaced.</strong></p>
    <div v-if="detecting" class="detect-wait" role="status"><strong>{{ detecting.title }}</strong><span>Now: {{ detecting.now }}{{ detecting.seconds?` · ${detecting.seconds} s`:'' }}</span><ol v-if="detecting.steps?.length"><li v-for="(step,i) in detecting.steps" :key="i" :class="step.state">{{ step.label }}</li></ol><span v-if="detecting.note">{{ detecting.note }}</span><UiButton @click="stopDetect">Stop waiting</UiButton></div>
    <ul v-else class="detect-list">
      <li v-if="meta?.given?.correction"><button @click="startFrom('correction')"><strong>The walls the app's user confirmed</strong><span>Often only the wall the user chose.</span></button></li>
      <li v-if="meta?.given?.ai"><button @click="startFrom('ai')"><strong>The walls the app's own AI marked</strong></button></li>
      <li v-for="src in meta?.detect?.sources||[]" :key="src.id"><button @click="runDetect(src.id)"><strong>{{ src.mode?`${src.mode}: `:'' }}{{ src.name }}</strong><UiBadge v-if="src.research_only" class="research-tag">Research or evaluation only</UiBadge><span v-if="src.what">{{ src.what }}</span><span>{{ src.detail }}. If it is not running it is started first, which takes a moment.</span><span v-if="src.licence">Licence: {{ src.licence }}. A label started from its answer says so, so that it can be left out later.</span></button></li>
      <li><button @click="startFrom('blank')"><strong>The empty photo</strong><span>Remove everything and draw by hand.</span></button></li>
    </ul>
    <p v-if="detectError" class="field-error" role="alert">{{ detectError }}</p>
    <form v-if="meta?.detect?.sources?.length" class="detect-choice" @submit.prevent="saveDetectChoice"><label class="field-label">When I open a photo nobody has drawn on<select v-model="detectChoice" class="text-input"><option value="">Do not let a model mark the walls by itself</option><option v-for="src in meta.detect.sources" :key="src.id" :value="src.id">Let {{ src.name }} mark the walls first{{ src.mode?` (${src.mode})`:'' }}</option></select></label><p class="field-help">This is your own choice in this project. A photo whose walls the app's user confirmed still opens with those.</p><UiButton type="submit">Save my choice</UiButton></form>
    <div class="dialog-actions"><UiButton @click="detectOpen=false">Close</UiButton></div>
  </UiDialog><UiDialog :open="reasonOpen" title="Request changes" @close="reasonOpen=false"><label class="field-label">What should the labeller change?<textarea v-model="reason" class="text-input" rows="4" maxlength="1000"/></label><p class="dialog-description">The label goes back to its labeller with this note.</p><div class="dialog-actions"><UiButton @click="reasonOpen=false">Cancel</UiButton><UiButton variant="primary" :disabled="busy||!reason.trim()" @click="sendBackLive">Send back</UiButton></div></UiDialog><UiDialog :open="!!toolDialog" :title="toolDialog" @close="toolDialog=''"><template v-if="toolDialog==='Editor help'"><p class="dialog-description">Polygon (P): click each corner; click the red first point, double-click or press Enter to finish. Backspace takes back the last point. Box (B): click one corner, then the opposite one, or drag. Split (S): click on both sides of a shape to cut it in two. Select (V): drag a corner; corners snap to other corners and the photo edge. Pan (H): drag the image. Click a corner and press Delete to remove it; double-click an edge to add one; Straighten (R) keeps only the real corners. Start from walls a model finds (M); AI refine replaces the selected shape with the one a model finds in the same place. After a shape is drawn, choose its class and press Enter. Esc cancels what is being drawn, Delete removes the selected shape, Ctrl+Z and Ctrl+Y undo and redo.</p></template><template v-else><UiBadge tone="purple">Coming soon</UiBadge><p class="dialog-description">{{ toolDialog }} is not available yet. Draw with the polygon or box tools, or start from what a model finds (Auto annotation).</p></template><div class="dialog-actions"><UiButton @click="toolDialog=''">Close</UiButton></div></UiDialog><UiDialog :open="leaving" title="Discard unsaved annotations?" @close="leaving=false"><p class="dialog-description">Your changes to this photo are not saved. Keep editing and save them, or discard them.</p><div class="dialog-actions"><U